const voidCall = `-- name: VoidCall :execrows
UPDATE calls SET outcome = 'interrupted', cost_nano = 0, fee_nano = 0 WHERE id = $1 AND ledger_tx_id IS NULL
`

func (q *Queries) VoidCall(ctx context.Context, id string) (int64, error) {
	result, err := q.db.Exec(ctx, voidCall, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
